def longestSubarray(nums, k):
    # Sieve of smallest prime factors up to the largest value
    limit = max(nums)
    spf = list(range(limit + 1))
    p = 2
    while p * p <= limit:
        if spf[p] == p:
            for m in range(p * p, limit + 1, p):
                if spf[m] == m:
                    spf[m] = p
        p += 1

    # Distinct prime factors of every element
    primes = []
    for v in nums:
        ps = []
        while v > 1:
            q = spf[v]
            ps.append(q)
            # Strip all copies of q so each prime is listed once
            while v % q == 0:
                v //= q
        primes.append(ps)

    # count[p] = how many elements inside the window have prime p as a factor
    count = {}
    best = 0
    left = 0
    for right in range(len(nums)):
        # Add the new element's primes to the window
        for q in primes[right]:
            count[q] = count.get(q, 0) + 1
        # Shrink from the left while the window has too many distinct primes
        while len(count) > k:
            for q in primes[left]:
                count[q] -= 1
                if count[q] == 0:
                    del count[q]
            left += 1
        # The window [left, right] is valid here (possibly empty if left passed right)
        if right - left + 1 > best:
            best = right - left + 1
    return best
